-- Tahap 8: consent wali pada profil + seed standar pertumbuhan (jangkar WHO 2006), jadwal imunisasi inti
-- (Kepmenkes 1098/2024), dan pangan TKPI. Cakupan seed dinyatakan terbuka di dokumen tahap.
ALTER TABLE health_profiles ADD COLUMN guardian_consent_at TEXT;
